#!/usr/bin/env python3
"""Bind successful independent R8 fit-project reviews to exact delivered artifacts."""
from pathlib import Path
import hashlib,json
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1];OUT=ROOT/'print/bambu-R8-fit-test-2026-10-24'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
reports={name:json.loads((HERE/name).read_text()) for name in ['qa-project.json','qa-toolpaths.json','qa-q01-fixture.json']}
assert all(row['status'].startswith('PASS') and row['failed_checks']==0 for row in reports.values())
project=OUT/'Fingerworker_R8_H2D_04mm_PLA_Fit_Test.3mf';sliced=OUT/'validation/Fingerworker_R8_slice_verification.gcode.3mf';layout=OUT/'plate-layout.json';fixture=OUT/'fixture/manifest.json'
assert reports['qa-project.json']['project_sha256']==reports['qa-toolpaths.json']['editable_project_sha256']==sha(project)
assert reports['qa-project.json']['layout_sha256']==reports['qa-toolpaths.json']['layout_sha256']==sha(layout)
assert reports['qa-q01-fixture.json']['fixture_manifest_sha256']==reports['qa-project.json']['fixture_manifest_sha256']==sha(fixture)
assert reports['qa-toolpaths.json']['sliced_archive_sha256']==sha(sliced)
files=[project,sliced,layout,fixture,*[HERE/n for n in reports],*[HERE/n for n in ['audit_bambu_project.py','audit_bambu_toolpaths.py','audit_q01_fixture.py','FIT_TEST_README.md','ASSEMBLY_DETAILS.md','PRINT_QA_NOTES.md','qa-orientation-study.json','qa_orientation_study.py']]]
result={'status':'PASS_PREPARED_UNLOADED_FIT_PROJECT','failed_checks':0,'unresolved_checks':0,'independent_check_count':sum(len(r['checks']) for r in reports.values()),'scope':'Full-size one-plate19-object H2D0.4 PLA unloaded hand-fit/manual-motion project; native source/triangles, rigid transforms, profiles/layout, actual sliced toolpaths/supports, separate p0 Q01 fixture assembly. Physical printed fit/comfort/tolerance and strength remain untested.','printer':'Bambu Lab H2D','nozzle_mm':.4,'filament':'PLA','bed':'Textured PEI Plate','plate_count':1,'object_count':19,'scale':1,'frozen_product_revision':'R8','source_sha256':'6099df42e341ff9f5c3439709a23107325d10ef922f616bdcda6fa6ef64d41c1','immutable_version_id':'6965afcca3af7c58ef3ac73f','fixture_source_sha256':reports['qa-q01-fixture.json']['fixture_source_sha256'],'report_statuses':{name:r['status'] for name,r in reports.items()},'files_sha256':{str(p.relative_to(ROOT)):sha(p) for p in files},'limitations':['Q01 is p0-only and has no axial latch; support the assembly and use gentle seating contact.','Four hard PLA pads and two printed rod proxies do not reproduce final material/friction/cushioning.','Real fasteners/compatible heat-set inserts are required; no functional printed threads are supplied.','No springs, preload, isometric loading, force measurement, calibration or500N qualification.'],'slicer_header':reports['qa-toolpaths.json']['header']}
(HERE/'qa-summary.json').write_text(json.dumps(result,indent=2)+'\n')
(HERE/'qa-summary.md').write_text('# R8 PLA fit project — independent review\n\n**PASS** — '+str(result['independent_check_count'])+' checks; zero failed or unresolved.\n\n19 full-size objects on one H2D/0.4 mm/textured-PEI plate. All source triangles and scale1 rigid transforms preserved; official PLA/H2D profiles and machine macros retained. Actual model/support/brim paths remain on the conservative shared bed and mutually separated. Every object has a nonempty first model layer; all four pad proxies finish at1.50 mm. Localized removable supports and clear rear tongue-guide interiors are checked. Q01 is one exact valid solid with checked portal/yoke datums and continuous unloaded assembly/motion paths.\n\nThe product CAD remains frozen R8. This review prepares a size/motion trial; it does not establish printed fit, comfort, insert retention, material capacity, sensor operation or a500N rating. Follow `FIT_TEST_README.md`.\n')
print(result['status'],result['independent_check_count'],sha(HERE/'qa-summary.json'))
